typedef float rational_t;
typedef float time_value_t;
typedef unsigned int uint32;
typedef int int32;

class stringx;
class entity;
class entity_anim_tree;

class entity_track_tree
{
  char file_header[4];
  uint32 version;
  int32 num_root_nodes;
  rational_t floor_offset;
  time_value_t duration;
public:
  time_value_t get_duration() const { return duration; }
};

class entity_anim_tree
{
public:
  entity_anim_tree(const stringx&, entity*, const entity_track_tree&,
                   const entity_track_tree&, rational_t, rational_t,
                   unsigned short, time_value_t, int, short);
};

class entity_widget
{
public:
  void add_anim(entity_anim_tree*);
};

class world_dynamics_system
{
public:
  void add_anim(entity_anim_tree*);
};

extern world_dynamics_system *g_world_ptr;

enum
{
  ANIM_REVERSE = 0x0002
};

#define START_PROF_TIMER(a) {}
#define STOP_PROF_TIMER(a) {}
#define assert(a) ((void)0)
#define NEW new

class anim_maker
{
public:
  entity_anim_tree* create_anim(const stringx& name,
                                const entity_track_tree& _tracka,
                                const entity_track_tree& _trackb,
                                rational_t blenda,
                                rational_t blendb,
                                entity* ent,
                                unsigned short flags,
                                time_value_t start_time,
                                int priority,
                                short loop,
                                entity_widget *owning_widget);
};

entity_anim_tree* anim_maker::create_anim( const stringx& name,
                                           const entity_track_tree& _tracka,
                                           const entity_track_tree& _trackb,
                                           rational_t blenda,
                                           rational_t blendb,
                                           entity* ent,
                                           unsigned short flags,
                                           time_value_t start_time,
                                           int priority,
                                           short loop,
                                           entity_widget *owning_widget )
{
 	START_PROF_TIMER( proftimer_create_anim3 );
  assert( ent );
#if defined(EVAN) && defined(PROJECT_KELLYSLATER)
	assert(false);
#endif
  entity_anim_tree* new_anim = 0;
  if ( flags & ANIM_REVERSE )
    start_time = _tracka.get_duration() - start_time;

  new_anim = NEW entity_anim_tree( name, ent, _tracka, _trackb, blenda, blendb, flags, start_time, priority, loop );

  if ( !owning_widget )
  {
    g_world_ptr->add_anim( new_anim );
  }
  else
  {
    owning_widget->add_anim( new_anim );
		assert(0);
  }
 	STOP_PROF_TIMER( proftimer_create_anim3 );
  return new_anim;
}
